from pathlib import Path

import pytest

from mnm_lang.assets import load_sprite_pack
from mnm_lang.examples import load_all_examples


@pytest.fixture(scope="session")
def repo_root() -> Path:
    return Path(__file__).resolve().parents[1]


@pytest.fixture(scope="session")
def sprite_pack():
    return load_sprite_pack()


@pytest.fixture(scope="session")
def examples():
    return {example.name: example for example in load_all_examples()}

from mnm_lang.render import decompile_rendered_image, render_source_to_image


def test_render_round_trip_examples(examples):
    for example in examples.values():
        image = render_source_to_image(example.source)
        decoded = decompile_rendered_image(image)
        assert decoded == example.source.strip()


def test_render_dimensions_are_positive(examples):
    image = render_source_to_image(examples["fizzbuzz"].source)
    assert image.width > 0
    assert image.height > 0

from pathlib import Path

from PIL import Image


def test_sprite_pack_files_exist(repo_root):
    sprite_dir = repo_root / "assets" / "sprites"
    for name in ["blue.png", "green.png", "red.png", "yellow.png", "orange.png", "brown.png", "palette.json"]:
        assert (sprite_dir / name).exists()


def test_sprite_dimensions_and_transparency(repo_root):
    sprite_dir = repo_root / "assets" / "sprites"
    for name in ["blue.png", "green.png", "red.png", "yellow.png", "orange.png", "brown.png"]:
        image = Image.open(sprite_dir / name).convert("RGBA")
        assert image.size == (128, 128)
        assert image.getchannel("A").getbbox() is not None
